#!/bin/sh
# Per-session browser-terminal container.
#
# The webapp logs in as `candidate` with a password generated by the
# facilitator for this session, so a shell inside one session cannot log into
# another session's terminal over the shared control network.
set -u

if [ -n "${REMOTE_TERMINAL_PASSWORD:-}" ]; then
    echo "candidate:${REMOTE_TERMINAL_PASSWORD}" | chpasswd
fi

exec /usr/sbin/sshd -D
